<?php
if(PHP_SAPI!=='cli')exit;require __DIR__.'/../app/Core/DB.php';$db=DB::getInstance();
$db->query("CREATE TABLE IF NOT EXISTS anggaran_pengesahan_neo(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,kd_wilayah VARCHAR(60) NOT NULL,kd_opd VARCHAR(60) NOT NULL,tahun INT NOT NULL,jenis ENUM('DPA','PARSIAL','PERUBAHAN') NOT NULL,urutan INT NOT NULL DEFAULT 0,nomor VARCHAR(255) NOT NULL,tanggal DATE NOT NULL,dasar_hukum TEXT NULL,status ENUM('DRAFT','DISAHKAN') NOT NULL DEFAULT 'DRAFT',username_insert VARCHAR(100),tgl_insert DATETIME DEFAULT CURRENT_TIMESTAMP,username_update VARCHAR(100),tgl_update DATETIME NULL,UNIQUE KEY uq_approval(kd_wilayah,kd_opd,tahun,jenis,urutan),KEY ix_effective(kd_wilayah,kd_opd,tahun,status,tanggal)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$db->query("CREATE TABLE IF NOT EXISTS anggaran_pengesahan_rincian_neo(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,pengesahan_id BIGINT UNSIGNED NOT NULL,tahap ENUM('dpa','dppa') NOT NULL,anggaran_id BIGINT NOT NULL,kd_sub_keg VARCHAR(80) NOT NULL,kd_akun VARCHAR(80) NULL,uraian TEXT NOT NULL,pagu DECIMAL(20,2) NOT NULL,UNIQUE KEY uq_snapshot(pengesahan_id,tahap,anggaran_id),KEY ix_source(tahap,anggaran_id),CONSTRAINT fk_approval_snapshot FOREIGN KEY(pengesahan_id) REFERENCES anggaran_pengesahan_neo(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
foreach(['kontrak_neo','kontrak_item_neo'] as$t){$cols=array_column($db->query('SHOW COLUMNS FROM '.$t)->fetchAll(),'Field');if(!in_array('pengesahan_anggaran_id',$cols))$db->query('ALTER TABLE '.$t.' ADD COLUMN pengesahan_anggaran_id BIGINT UNSIGNED NULL');}
echo "Approval schema ready; official dates not fabricated.\n";
